import java.util.List;

public class Filmliste {

    public static void main(String[] args) {
        List<String> filme = List.of("Up", "Interstellar", "Coco");

        System.out.println("Lange Titel:");
        filme.stream()
             .filter(titel -> titel.length() > 4)
             .forEach(titel -> System.out.println("- " + titel));

        long anzahl = filme.stream().count();
        System.out.println("Gesamt: " + anzahl);
    }
}

