import java.util.List;

public class Namensfilter {

    public static void main(String[] args) {
        List<String> namen = List.of("Anna", "Bob", "Christian");

        namen.stream()
             .filter(n -> n.length() > 3)
             .forEach(n -> System.out.println("- " + n));

        System.out.println("Gesamt: " + namen.size());
    }
}
